{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket does not have versioning enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket configuration lacks a `versioning` block. Without versioning, accidental deletions or overwrites of objects cannot be recovered, and it is a best practice for data integrity and compliance."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = var.bucket_acl
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }
  versioning {
    enabled = true
  }
}",
  "fix_summary": "Added the `versioning` block with `enabled = true` to the `aws_s3_bucket.bucket_2` resource to ensure object versions are retained, mitigating risks associated with accidental deletion or overwrite."
}
